import{_ as t,o as r,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Projektduplicator 2026","description":"Dupliquer et modifier des projets de modèles EEP avec interface multilingue, sauvegardes ZIP et mises à jour GitHub manuelles.","frontmatter":{"title":"Projektduplicator 2026","description":"Dupliquer et modifier des projets de modèles EEP avec interface multilingue, sauvegardes ZIP et mises à jour GitHub manuelles."},"headers":[],"relativePath":"fr/eep/projektduplicator-2026/index.md","filePath":"fr/eep/projektduplicator-2026/index.md","lastUpdated":1792851046000}'),i={name:"fr/eep/projektduplicator-2026/index.md"};function o(n,e,l,d,u,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="projektduplicator-2026" tabindex="-1">Projektduplicator 2026 <a class="header-anchor" href="#projektduplicator-2026" aria-label="Permalink to &quot;Projektduplicator 2026&quot;">​</a></h1><p>Projektduplicator 2026 est l’outil Windows indépendant d’UGSo Software pour dupliquer et modifier des projets de modèles EEP. L’interface est disponible en allemand, anglais, français et néerlandais.</p><h2 id="telechargement-et-demarrage" tabindex="-1">Téléchargement et démarrage <a class="header-anchor" href="#telechargement-et-demarrage" aria-label="Permalink to &quot;Téléchargement et démarrage&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/download/v4.6.6.59/Projektduplicator-2026-v4.6.6.59-windows.zip" target="_blank" rel="noreferrer">Télécharger le ZIP Windows 4.6.6.59</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/tag/v4.6.6.59" target="_blank" rel="noreferrer">Version, empreinte SHA-256 et sources</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026" target="_blank" rel="noreferrer">Dépôt GitHub</a></li></ul><p>Extraire tout le ZIP dans un dossier accessible en écriture et lancer <code>Projektduplicator_2017.exe</code>. Ce nom technique est conservé pour assurer la compatibilité des paramètres existants. Windows avec .NET Framework 4.8 est nécessaire ; la solution se compile dans Visual Studio 2026.</p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><ul><li>Dupliquer des projets de modèles EEP et modifier les informations des modèles.</li><li>Modifier les noms et descriptions multilingues et les traduire avec Google Translate.</li><li>Changer la langue de l’interface pendant l’utilisation.</li><li>Créer des instantanés ZIP des projets dans le dossier de sauvegarde configuré.</li><li>Rechercher manuellement des versions GitHub avec les boutons de mise à jour, les télécharger et les installer après confirmation.</li></ul><p>La traduction Web Google nécessite Internet et dépend du format des réponses du site Google. Elle n’utilise pas d’API officielle de Google. En cas d’échec, les textes existants sont conservés.</p><h2 id="parametres-et-mises-a-jour" tabindex="-1">Paramètres et mises à jour <a class="header-anchor" href="#parametres-et-mises-a-jour" aria-label="Permalink to &quot;Paramètres et mises à jour&quot;">​</a></h2><p>Sauvegarder les projets avant toute modification. Fermer les éditeurs et enregistrer les listes de chemins et de splines avant une mise à jour. Aucune recherche automatique de mise à jour n’a lieu au démarrage.</p><p>Le programme de mise à jour vérifie le paquet et son empreinte SHA-256, sauvegarde les fichiers du programme et les paramètres existants, puis redémarre après une installation réussie. Projets, listes de chemins et contenu personnalisé d’<code>info.txt</code> sont conservés. Si <code>info.txt</code> manque, la copie fournie est installée ; une copie ancienne existante n’est volontairement pas remplacée automatiquement.</p><h2 id="version-verifiee" tabindex="-1">Version vérifiée <a class="header-anchor" href="#version-verifiee" aria-label="Permalink to &quot;Version vérifiée&quot;">​</a></h2><p>La version 4.6.6.59 a été approuvée par l’utilisateur après contrôle local. Le concepteur Form1 a été vérifié dans Visual Studio. La description et les remerciements d’<code>info.txt</code> ont été révisés en DE/EN/FR/NL. Les 49 vérifications locales ont réussi : langues, correspondance des champs, validation du paquet, conservation des données, annulation, restauration et transfert entre processus.</p><p>Un test réel de mise à jour depuis la version GitHub publique, avec installation et redémarrage, reste à effectuer séparément. Les vérifications actuelles utilisent des réponses GitHub simulées et des installations temporaires.</p><h2 id="sources-et-mentions" tabindex="-1">Sources et mentions <a class="header-anchor" href="#sources-et-mentions" aria-label="Permalink to &quot;Sources et mentions&quot;">​</a></h2><p>Le code UGSo est sous licence MIT ; les dépendances conservent leurs licences et copyrights respectifs. Voir <code>LICENSE</code> et <code>THIRD-PARTY-NOTICES.md</code> dans le dépôt. EEP et Google Translate appartiennent à leurs titulaires respectifs.</p>',16)])])}const f=t(i,[["render",o]]);export{m as __pageData,f as default};
